"""G8.3: somente lacunas do cadastro; mantém os cenários G8.2 como regressão."""
from pathlib import Path
import unittest,subprocess
import test_registry_integration_browser as g82
import test_frontend_access as base
D=g82.D;M=g82.M
class RegistryConsolidationBrowserTests(g82.RegistryIntegrationBrowserTests):
    @classmethod
    def setUpClass(cls):
        g82.RegistryIntegrationBrowserTests.setUpClass.__func__(cls)
        subprocess.run(['python','scripts/export_preview.py','--registry-consolidation-preview','--output',str(Path(cls.tmp.name)/'index.html')],cwd=base.ROOT,check=True,capture_output=True)
    def create(self,name='Pessoa Completa G83',preferred='Árvore Preferida',active=True):
        return self.page.evaluate("""async({name,preferred,active})=>{
          const id=crypto.randomUUID();await IASDPISchedules.request('iasdpi_registry_save',{p_person:id,p_expected_person_version:0,p_person_patch:{name,display_name:preferred,active},p_links:[],p_request_id:crypto.randomUUID()});return id;
        }""",dict(name=name,preferred=preferred,active=active))
    def refresh(self):self.go('church-home');self.page.wait_for_selector('.church-portal-cards');self.page.evaluate("window.dispatchEvent(new Event('iasdpi-registry-saved'))");self.registry()
    def person_row(self,p):return self.page.locator('[data-registry-person-row="'+p+'"]')
    def test_directory_filters_name_preferred_status_and_unlinked_combined(self):
        self.admin();p=self.create(active=False);self.registry();self.page.fill('#registry-search','arvore');self.page.select_option('#registry-person-status','inactive');self.page.select_option('#registry-person-department','none');self.assertEqual(self.page.locator('[data-registry-person-row]').count(),1);self.assertTrue(self.person_row(p).is_visible());self.assertIn('Pessoa Completa G83',self.person_row(p).inner_text());self.assertIn('Árvore Preferida',self.person_row(p).inner_text())
        self.page.select_option('#registry-person-status','active');self.assertEqual(self.page.locator('[data-registry-person-row]').count(),0);self.assertIn('Nenhuma pessoa corresponde',self.page.locator('#registry-people-results').inner_text());self.assertNotIn('Erro',self.page.locator('#registry-people-results').inner_text())
        self.page.locator('[data-registry-clear-filters]').click();self.assertGreater(self.page.locator('[data-registry-person-row]').count(),1)
    def test_edit_person_status_preserves_id_and_shows_church(self):
        self.admin();p=self.create();self.registry();count=len(self.catalog()['people']);self.person_row(p).locator('[data-registry-edit-person]').click();form=self.page.locator('#registry-person');self.assertTrue(form.locator('[name=active]').is_checked());self.assertIn('Parada Inglesa',form.inner_text());form.locator('[name=active]').uncheck();self.page.once('dialog',lambda d:d.accept());form.locator('button[type=submit],button:not([type])').last.click();self.page.wait_for_function("()=>document.querySelector('[data-registry-status]')?.textContent.includes('confirmadas')")
        self.assertIn('Inativa',self.person_row(p).inner_text());self.assertEqual(len(self.catalog()['people']),count);self.assertEqual(self.person_row(p).count(),1)
    def test_one_person_view_edits_three_links_without_erasing_pending_other_link(self):
        self.admin();self.registry();p=self.person();c=self.catalog();deps=[d for d in c['departments'] if d['code'] in ['sonoplastia','musica','comunicacao']]
        self.page.evaluate("""async({person,departments})=>{const c=await IASDPISchedules.request('iasdpi_registry_catalog');const links=departments.filter(d=>!c.memberships.some(m=>m.person_id===person&&m.department_id===d.id)).map(d=>({department_id:d.id,expected_version:0,patch:{}}));await IASDPISchedules.request('iasdpi_registry_save',{p_person:person,p_expected_person_version:c.people.find(p=>p.id===person).version,p_person_patch:{},p_links:links,p_request_id:crypto.randomUUID()});}""",{'person':p['id'],'departments':deps})
        self.refresh();self.person_row(p['id']).locator('[data-registry-person-links]').click();self.assertEqual(self.page.locator('[data-registry-member]').count(),3)
        c=self.catalog();members=[m for m in c['memberships'] if m['person_id']==p['id']];music=next(m for m in members if m['department_id']==M);communication=next(m for m in members if m['department_id'] not in [D,M]);a=self.page.locator('[data-registry-member="'+music['id']+'"]');self.page.evaluate("()=>{const previous=IASDPISchedulePreview.request;IASDPISchedulePreview.request=(n,b)=>{if(n==='iasdpi_registry_history')window.g83HistoryDepartment=b.p_department;return previous(n,b);};}");a.locator('[data-registry-history]').click();self.page.wait_for_function("()=>Boolean(window.g83HistoryDepartment)");self.assertEqual(self.page.evaluate('window.g83HistoryDepartment'),M);b=self.page.locator('[data-registry-member="'+communication['id']+'"]');b.locator('[name=max_monthly_count]').fill('2');a.locator('[name=max_monthly_count]').fill('4');self.page.once('dialog',lambda d:d.accept());a.locator('button[type=submit]').click();self.page.wait_for_function("()=>document.querySelector('[data-registry-status]')?.textContent.includes('confirmadas')")
        self.assertEqual(b.locator('[name=max_monthly_count]').input_value(),'2');self.assertIn('pendentes',b.locator('[role=status]').inner_text());self.assertEqual(self.page.locator('[data-registry-member]').count(),3);self.assertIsNone(next(m for m in self.catalog()['memberships'] if m['id']==communication['id']).get('max_monthly_count'))
    def test_private_contacts_reuse_original_editor_and_survive_public_name_edit(self):
        self.admin();self.registry();p=self.person();self.person_row(p['id']).locator('[data-registry-edit-person]').click();self.page.locator('[data-registry-private-person]').click();self.page.wait_for_selector('#schedule-editor [name=contact]');self.page.locator('#schedule-editor [name=contact]').fill('Contato privado fictício G83');self.page.locator('#schedule-editor [name=notes]').fill('Nota privada fictícia');self.page.locator('#schedule-editor button[type=submit]').click();self.page.wait_for_function("()=>!document.querySelector('#schedule-editor')&&document.querySelector('.schedule-feedback')?.textContent.includes('salvo')")
        self.registry();self.assertNotIn('Contato privado fictício G83',self.page.locator('#app').inner_text());self.page.evaluate("""async id=>{const people=await IASDPISchedules.request('iasdpi_registry_people',{p_search:''});await IASDPISchedules.request('iasdpi_registry_save',{p_person:id,p_expected_person_version:people.find(p=>p.id===id).version,p_person_patch:{display_name:'Luan preferido G83'},p_links:[],p_request_id:crypto.randomUUID()});}""",p['id'])
        details=self.page.evaluate("id=>IASDPISchedules.request('iasdpi_schedule_person_details',{p_id:id})",p['id']);self.assertEqual(details['contact'],'Contato privado fictício G83');self.assertEqual(details['notes'],'Nota privada fictícia')
    def test_leader_directory_scoped_without_private_editor_or_other_links(self):
        self.login('som.teste');self.registry();c=self.catalog();own={m['person_id'] for m in c['memberships'] if m['department_id']==D};visible=set(self.page.locator('[data-registry-person-row]').evaluate_all('rows=>rows.map(r=>r.dataset.registryPersonRow)'));self.assertEqual(visible,own);self.assertEqual(self.page.locator('[data-registry-edit-person],[data-registry-private-person]').count(),0)
        denied=self.page.evaluate("async id=>{try{await IASDPISchedules.request('iasdpi_schedule_person_details',{p_id:id});return false;}catch{return true;}}",next(iter(own)));self.assertTrue(denied)
    def test_search_keeps_unsaved_link_fields_and_guard(self):
        self.admin();self.registry();self.page.select_option('#registry-department',D);p=self.person();self.row(p).locator('[name=max_monthly_count]').fill('6');self.page.fill('#registry-search','Luan');self.assertEqual(self.row(p).locator('[name=max_monthly_count]').input_value(),'6');self.page.once('dialog',lambda d:d.dismiss());self.go('schedule-calendar');self.assertTrue(self.page.locator('#registry-search').is_visible())
    def test_directory_five_widths_keyboard_and_visual(self):
        self.admin();self.registry();out=base.ROOT/'dist/registry-g83';out.mkdir(exist_ok=True,parents=True)
        for width in [360,390,768,1024,1440]:self.page.set_viewport_size(dict(width=width,height=900));self.assertLessEqual(self.page.evaluate('document.documentElement.scrollWidth'),width)
        self.page.focus('#registry-search');self.page.keyboard.type('Luan');self.assertGreater(self.page.locator('[data-registry-person-row]').count(),0);self.page.keyboard.press('Tab');self.assertEqual(self.page.evaluate('document.activeElement.id'),'registry-person-status');self.page.locator('[data-registry-clear-filters]').click()
        for width,label in [(390,'mobile'),(1440,'desktop')]:self.page.set_viewport_size(dict(width=width,height=900));self.page.screenshot(path=str(out/('registry-g83-'+label+'.png')),full_page=True)
